"use client";

import { Toast, type ToastManager as BaseToastManager } from "@base-ui/react/toast";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { type HTMLAttributes, type ReactNode, useEffect, useRef, useState } from "react";
import { cn } from "@/lib/utils";
import { useIcon } from "@/lib/icon-context";
import { useShape } from "@/lib/shape-context";
import { useSize } from "@/lib/size-context";
import { useSurface } from "@/lib/surface-context";
import { surfaceClasses } from "@/lib/surface-classes";
import { spring } from "@/lib/springs";
import { fontWeights } from "@/lib/font-weight";
import { Button } from "@/components/ui/button";

export type ToastVariant = "default" | "success" | "info" | "warning" | "error" | "loading";
export type ToastPosition =
  | "top-left"
  | "top-center"
  | "top-right"
  | "bottom-left"
  | "bottom-center"
  | "bottom-right";
export type ToastAction = { label: string; onClick: () => void };

export interface ToastOptions {
  description?: ReactNode;
  duration?: number;
  id?: string;
  action?: ToastAction;
  dismissible?: boolean;
}

export interface ToastMessageOptions extends ToastOptions {
  title: ReactNode;
}

export interface ToastUpdateOptions extends ToastOptions {
  variant?: ToastVariant;
}

export interface ToastPromiseMessages<Value> {
  loading: string | ToastMessageOptions;
  success: string | ToastMessageOptions | ((value: Value) => string | ToastMessageOptions);
  error: string | ToastMessageOptions | ((error: unknown) => string | ToastMessageOptions);
}

export interface ToastData {
  variant: ToastVariant;
  action?: ToastAction;
  dismissible: boolean;
}

export type ToastManager = BaseToastManager<ToastData>;
export type ToastApi = ((title: ReactNode, options?: ToastOptions) => string) & {
  success(title: ReactNode, options?: ToastOptions): string;
  info(title: ReactNode, options?: ToastOptions): string;
  warning(title: ReactNode, options?: ToastOptions): string;
  error(title: ReactNode, options?: ToastOptions): string;
  loading(title: ReactNode, options?: ToastOptions): string;
  dismiss(id?: string): void;
  update(id: string, title: ReactNode, options?: ToastUpdateOptions): void;
  promise<Value>(promise: Promise<Value>, messages: ToastPromiseMessages<Value>): Promise<Value>;
};

/** Each Toaster can own a manager, keeping docs and embedded demos isolated. */
export const createBoringToastManager = () => Toast.createToastManager<ToastData>();
const defaultManager = createBoringToastManager();
const toastApis = new WeakMap<object, ToastApi>();
let toastIdCounter = 0;

function messageParts(value: string | ToastMessageOptions) {
  return typeof value === "string" ? { title: value } : value;
}

export function createToastApi(manager: ToastManager): ToastApi {
  const existingApi = toastApis.get(manager);
  if (existingApi) return existingApi;
  const records = new Map<
    string,
    { type: ToastVariant; description?: ReactNode; timeout?: number; data: ToastData }
  >();

  const add = (title: ReactNode, variant: ToastVariant, options: ToastOptions = {}) => {
    if (typeof window === "undefined") return "";
    const id = options.id ?? `bui-toast-${++toastIdCounter}`;
    const data: ToastData = {
      variant,
      action: options.action,
      dismissible: options.dismissible ?? true,
    };
    const actionProps = options.action
      ? {
          children: options.action.label,
          onClick: () => {
            try {
              options.action?.onClick();
            } finally {
              manager.close(id);
            }
          },
        }
      : undefined;
    const record = {
      type: variant,
      description: options.description,
      timeout: variant === "loading" ? 0 : options.duration,
      data,
    };
    records.set(id, record);
    manager.add({
      id,
      title,
      description: record.description,
      timeout: record.timeout,
      type: variant,
      data,
      actionProps,
      onRemove: () => records.delete(id),
    });
    return id;
  };

  const api = Object.assign(
    (title: ReactNode, options?: ToastOptions) => add(title, "default", options),
    {
      success: (title: ReactNode, options?: ToastOptions) => add(title, "success", options),
      info: (title: ReactNode, options?: ToastOptions) => add(title, "info", options),
      warning: (title: ReactNode, options?: ToastOptions) => add(title, "warning", options),
      error: (title: ReactNode, options?: ToastOptions) => add(title, "error", options),
      loading: (title: ReactNode, options?: ToastOptions) =>
        add(title, "loading", { ...options, duration: 0 }),
      dismiss: (id?: string) => manager.close(id),
      update: (id: string, title: ReactNode, options: ToastUpdateOptions = {}) => {
        const previous = records.get(id);
        if (!previous) return;
        const variant =
          options.variant ??
          (previous?.type === "loading" ? "default" : (previous?.type ?? "default"));
        const description = Object.hasOwn(options, "description")
          ? options.description
          : previous?.description;
        const action = Object.hasOwn(options, "action") ? options.action : previous?.data.action;
        const dismissible = Object.hasOwn(options, "dismissible")
          ? (options.dismissible ?? true)
          : (previous?.data.dismissible ?? true);
        const timeout = Object.hasOwn(options, "duration")
          ? options.duration
          : previous?.type === "loading"
            ? undefined
            : previous?.timeout;
        const data: ToastData = { variant, action, dismissible };
        const actionProps = action
          ? {
              children: action.label,
              onClick: () => {
                try {
                  action.onClick();
                } finally {
                  manager.close(id);
                }
              },
            }
          : undefined;
        records.set(id, { type: variant, description, timeout, data });
        manager.update(id, { title, description, timeout, type: variant, data, actionProps });
      },
      promise: <Value,>(promise: Promise<Value>, messages: ToastPromiseMessages<Value>) => {
        if (typeof window === "undefined") return promise;
        const loading = messageParts(messages.loading);
        const id = add(loading.title, "loading", { ...loading, duration: 0 });
        return promise.then(
          (value) => {
            const success = messageParts(
              typeof messages.success === "function" ? messages.success(value) : messages.success,
            );
            api.update(id, success.title, { ...success, variant: "success" });
            return value;
          },
          (error: unknown) => {
            const failure = messageParts(
              typeof messages.error === "function" ? messages.error(error) : messages.error,
            );
            api.update(id, failure.title, { ...failure, variant: "error" });
            throw error;
          },
        );
      },
    },
  ) satisfies ToastApi;
  toastApis.set(manager, api);
  return api;
}

export const toast = createToastApi(defaultManager);

export interface ToasterProps extends HTMLAttributes<HTMLDivElement> {
  /** Manager created with createBoringToastManager. Defaults to the shared toast API manager. */
  manager?: ReturnType<typeof createBoringToastManager>;
  position?: ToastPosition;
  /** Portal target; defaults to document.body. */
  container?: HTMLElement | null;
  /** Render the viewport in place, useful for bounded previews. */
  inline?: boolean;
  /** Defaults to 5 seconds; set to 0 to keep notifications until dismissed. */
  duration?: number;
  limit?: number;
}

export function Toaster({
  manager = defaultManager,
  position = "top-center",
  container,
  inline = false,
  duration = 5000,
  limit = 4,
  className,
  ...props
}: ToasterProps) {
  const placement = position.split("-");
  const vertical = placement[0];
  const horizontal = placement[1];
  const viewport = (
    <Toast.Viewport
      className={cn(
        "pointer-events-none z-[100] flex w-full flex-col gap-0 outline-none",
        inline ? "absolute inset-x-0" : "fixed inset-x-0",
        vertical === "top" ? "top-0" : "bottom-0",
        horizontal === "left"
          ? "items-start"
          : horizontal === "right"
            ? "items-end"
            : "items-center",
        className,
      )}
      {...props}
    >
      <ToasterItems position={position} />
    </Toast.Viewport>
  );

  return (
    <Toast.Provider toastManager={manager} timeout={duration} limit={limit}>
      {inline ? (
        viewport
      ) : (
        <Toast.Portal container={container ?? undefined}>{viewport}</Toast.Portal>
      )}
    </Toast.Provider>
  );
}

function ToasterItems({ position }: { position: ToastPosition }) {
  const { toasts } = Toast.useToastManager<ToastData>();
  const shape = useShape();
  const size = useSize();
  const compact = size.variant === "compact";
  const substrate = useSurface();
  const level = Math.min(substrate + 2, 8);
  const reduceMotion = useReducedMotion();
  const [holding, setHolding] = useState(false);
  const slots = useRef(
    new Map<
      string,
      {
        y: number;
        scale: number;
        opacity: number;
        behind: boolean;
        hidden: boolean;
        index: number;
        capWidth?: number;
        capHeight?: number;
      }
    >(),
  );
  useEffect(() => {
    const ids = new Set(toasts.map((item) => item.id));
    for (const id of slots.current.keys()) {
      if (!ids.has(id)) slots.current.delete(id);
    }
  }, [toasts]);
  useEffect(() => {
    if (!holding) return;
    const release = () => setHolding(false);
    window.addEventListener("pointerup", release);
    window.addEventListener("pointercancel", release);
    return () => {
      window.removeEventListener("pointerup", release);
      window.removeEventListener("pointercancel", release);
    };
  }, [holding]);
  const Check = useIcon("check");
  const Info = useIcon("info");
  const Loader = useIcon("loader");
  const Close = useIcon("x");

  const icons: Partial<Record<ToastVariant, ReturnType<typeof useIcon>>> = {
    success: Check,
    info: Info,
    loading: Loader,
  };
  const tones: Record<ToastVariant, string> = {
    default: "text-foreground",
    success: "text-[color:var(--success)]",
    info: "text-[color:var(--info)]",
    warning: "text-[color:var(--warning)]",
    error: "text-destructive",
    loading: "text-muted-foreground",
  };
  const radius = shape.container;
  const sizeClass = compact ? "px-2.5 py-1.5" : "px-3 py-2";
  const front = toasts.find((item) => item.transitionStatus !== "ending" && !item.limited);

  return (
    <>
      <style>{`@keyframes boring-toast-exit { to { opacity: 0; } }`}</style>
      {toasts.map((item, listIndex) => {
        const variant = item.data?.variant ?? (item.type as ToastVariant) ?? "default";
        const StatusIcon = icons[variant];
        const data = item.data;
        return (
          <Toast.Root
            key={item.id}
            toast={item}
            swipeDirection={["up", "down", "left", "right"]}
            className={({ transitionStatus, swiping, limited }) =>
              cn(
                "pointer-events-auto w-fit max-w-[min(24rem,calc(100vw-2rem))] touch-pan-y outline-none focus-visible:ring-2 focus-visible:ring-[color:var(--focus-ring,#6B97FF)] focus-visible:ring-offset-2 focus-visible:ring-offset-background",
                swiping && "select-none",
                transitionStatus === "ending" && "pointer-events-none",
                limited && "invisible",
              )
            }
            render={(rootProps, state) => {
              const { style: baseStyle, ...rest } = rootProps as HTMLAttributes<HTMLDivElement>;
              const exiting = state.transitionStatus === "ending";
              const expanded = state.expanded || holding;
              const visibleIndex = Number.parseInt(
                (baseStyle as Record<string, string> | undefined)?.["--toast-index"] ??
                  String(listIndex),
                10,
              );
              const direction = position.startsWith("top") ? 1 : -1;
              const depth = Math.min(visibleIndex, 2);
              const itemHeight =
                item.height || item.ref?.current?.offsetHeight || (compact ? 34 : 38);
              const frontHeight = front?.height || itemHeight;
              const drop =
                !expanded && visibleIndex > 0 ? Math.max(0, frontHeight - itemHeight) : 0;
              const collapsedY = (depth * 10 + drop) * direction;
              const baseOffset = Number.parseFloat(
                (baseStyle as Record<string, string> | undefined)?.["--toast-offset-y"] ?? "0",
              );
              const fanY = visibleIndex === 0 ? 0 : (baseOffset + visibleIndex * 8) * direction;
              const currentSlot = {
                y: expanded ? fanY : collapsedY,
                scale: expanded ? 1 : 1 - depth * 0.03,
                opacity: expanded ? 1 : visibleIndex < 3 ? 1 - depth * 0.15 : 0,
                behind: !expanded && visibleIndex > 0,
                hidden: !expanded && visibleIndex >= 3,
                index: visibleIndex,
                capWidth: front?.ref?.current?.offsetWidth,
                capHeight: frontHeight,
              };
              // Base UI clears a closing toast's height immediately. Keep its last
              // visible slot while the inner native fade and outer movement finish.
              const slot = exiting ? (slots.current.get(item.id) ?? currentSlot) : currentSlot;
              if (!exiting) slots.current.set(item.id, currentSlot);
              const behind = slot.behind;
              const hiddenDepth = slot.hidden;
              const enteringY = slot.y - 8 * direction;
              const horizontalOrigin = position.endsWith("left")
                ? "left"
                : position.endsWith("right")
                  ? "right"
                  : "center";
              return (
                <motion.div
                  initial={
                    reduceMotion
                      ? false
                      : {
                          opacity: 0,
                          y: enteringY,
                          scale: slot.scale * 0.98,
                        }
                  }
                  animate={
                    exiting
                      ? {
                          opacity: reduceMotion ? 0 : slot.opacity,
                          y: reduceMotion ? slot.y : enteringY,
                          scale: reduceMotion ? slot.scale : slot.scale * 0.96,
                        }
                      : {
                          opacity: slot.opacity,
                          y: slot.y,
                          scale: slot.scale,
                        }
                  }
                  transition={
                    reduceMotion ? { duration: 0 } : exiting ? spring.slow.exit : spring.slow
                  }
                  className={cn(
                    "pointer-events-none absolute inset-x-0 flex px-4",
                    position.startsWith("top") ? "top-4" : "bottom-4",
                    position.endsWith("left")
                      ? "justify-start"
                      : position.endsWith("right")
                        ? "justify-end"
                        : "justify-center",
                  )}
                  style={{
                    transformOrigin: `${position.startsWith("top") ? "top" : "bottom"} ${horizontalOrigin}`,
                    zIndex: exiting ? 0 : 100 - slot.index,
                  }}
                >
                  <motion.div
                    layout="size"
                    transition={reduceMotion ? { duration: 0 } : spring.slow}
                    className={cn(
                      "relative",
                      behind
                        ? "pointer-events-none overflow-hidden"
                        : "pointer-events-auto overflow-visible before:absolute before:inset-x-0 before:-inset-y-1 before:content-['']",
                      radius,
                    )}
                    style={{
                      maxWidth:
                        behind && slot.capWidth ? slot.capWidth : "min(24rem, calc(100vw - 2rem))",
                      maxHeight: behind ? slot.capHeight : undefined,
                    }}
                  >
                    <div
                      {...rest}
                      style={{
                        ...baseStyle,
                        width: "max-content",
                        maxWidth: "min(24rem, calc(100vw - 2rem))",
                        animation:
                          exiting && !reduceMotion
                            ? `boring-toast-exit ${spring.slow.exit.duration}s ease-out both`
                            : undefined,
                      }}
                      aria-hidden={behind || hiddenDepth ? true : rest["aria-hidden"]}
                      inert={behind || hiddenDepth ? true : rest.inert}
                      tabIndex={behind || hiddenDepth ? -1 : rest.tabIndex}
                      onPointerDown={(event) => {
                        rest.onPointerDown?.(event);
                        setHolding(true);
                      }}
                      className={cn(
                        rest.className,
                        "relative",
                        radius,
                        "border border-border/70 shadow-none",
                        surfaceClasses(level, 3),
                        sizeClass,
                        (behind || hiddenDepth) && "pointer-events-none",
                      )}
                    >
                      <Toast.Content
                        className={cn(
                          "flex",
                          item.description ? "items-start" : "items-center",
                          size.gap,
                          behind && "pointer-events-none",
                        )}
                        style={{
                          opacity: behind ? 0 : 1,
                          transition: reduceMotion
                            ? "none"
                            : `opacity ${spring.slow.duration}s ease-out`,
                        }}
                      >
                        <AnimatePresence initial={false} mode="popLayout">
                          {(StatusIcon || variant === "warning" || variant === "error") && (
                            <motion.span
                              key={variant}
                              initial={
                                reduceMotion
                                  ? false
                                  : { opacity: 0, scale: 0.25, filter: "blur(4px)" }
                              }
                              animate={{ opacity: 1, scale: 1, filter: "blur(0px)" }}
                              exit={{
                                opacity: 0,
                                scale: 0.25,
                                filter: "blur(4px)",
                                transition: reduceMotion ? { duration: 0 } : spring.fast.exit,
                              }}
                              transition={reduceMotion ? { duration: 0 } : spring.slow}
                              className={cn(
                                "shrink-0",
                                item.description && "mt-0.5",
                                tones[variant],
                              )}
                              aria-hidden="true"
                            >
                              {StatusIcon ? (
                                <StatusIcon
                                  className={cn(
                                    variant === "loading" && "motion-safe:animate-spin",
                                  )}
                                  size={size.icon}
                                />
                              ) : (
                                <span
                                  className="flex items-center justify-center rounded-full border font-semibold leading-none"
                                  style={{
                                    width: size.icon,
                                    height: size.icon,
                                    fontSize: compact ? 9 : 10,
                                  }}
                                >
                                  {variant === "warning" ? "!" : "×"}
                                </span>
                              )}
                            </motion.span>
                          )}
                        </AnimatePresence>
                        <div
                          className={cn(
                            "min-w-0 flex-1",
                            item.description && "w-[min(20rem,calc(100vw-7rem))]",
                          )}
                        >
                          <AnimatePresence initial={false} mode="popLayout">
                            {item.title && (
                              <motion.div
                                key={`${item.updateKey}-title`}
                                initial={reduceMotion ? false : { opacity: 0, filter: "blur(4px)" }}
                                animate={{ opacity: 1, filter: "blur(0px)" }}
                                exit={{
                                  opacity: 0,
                                  filter: "blur(4px)",
                                  transition: reduceMotion ? { duration: 0 } : spring.fast.exit,
                                }}
                                transition={reduceMotion ? { duration: 0 } : spring.slow}
                                className="max-w-full"
                              >
                                <Toast.Title
                                  className={cn(
                                    compact ? "text-[12px]" : "text-[13px]",
                                    "leading-5 text-foreground",
                                  )}
                                  style={{ fontVariationSettings: fontWeights.semibold }}
                                >
                                  {item.title}
                                </Toast.Title>
                              </motion.div>
                            )}
                          </AnimatePresence>
                          <AnimatePresence initial={false} mode="popLayout">
                            {item.description && (
                              <motion.div
                                key={`${item.updateKey}-description`}
                                initial={
                                  reduceMotion
                                    ? false
                                    : { height: 0, opacity: 0, filter: "blur(4px)" }
                                }
                                animate={{ height: "auto", opacity: 1, filter: "blur(0px)" }}
                                exit={{
                                  height: 0,
                                  opacity: 0,
                                  filter: "blur(4px)",
                                  transition: reduceMotion ? { duration: 0 } : spring.fast.exit,
                                }}
                                transition={reduceMotion ? { duration: 0 } : spring.slow}
                                className="overflow-hidden"
                              >
                                <Toast.Description
                                  className={cn(
                                    "mt-0.5 block leading-4 text-muted-foreground",
                                    compact ? "text-[11px]" : "text-[12px]",
                                  )}
                                >
                                  {item.description}
                                </Toast.Description>
                              </motion.div>
                            )}
                          </AnimatePresence>
                        </div>
                        {data?.action && (
                          <Toast.Action
                            render={
                              <Button variant="tertiary" size={compact ? "sm" : "md"}>
                                {data.action.label}
                              </Button>
                            }
                          >
                            {data.action.label}
                          </Toast.Action>
                        )}
                        {data?.dismissible !== false && (
                          <Toast.Close
                            render={
                              <Button
                                variant="ghost"
                                size="icon-sm"
                                aria-label="Dismiss notification"
                                className="-my-1 -mr-1 h-7 w-7 shrink-0"
                              >
                                <Close aria-hidden="true" />
                              </Button>
                            }
                          />
                        )}
                      </Toast.Content>
                    </div>
                  </motion.div>
                </motion.div>
              );
            }}
          />
        );
      })}
    </>
  );
}
